  app.innerHTML=`<section class="scene"><img src="./data/art/valley-hub.png" alt="山の先にある谷の記録所"><h1>谷の記録所</h1><p>山道を越えた谷には、各地から届く荷物と届け先の記録が集まっています。</p><div class="characters"><figure><img src="./data/art/valley-keeper.png" alt="帳面と鉛筆を持つ谷の記録係ユノ"><figcaption><strong>ユノ</strong><br>荷物と届け先の記録係</figcaption></figure></div>${dialogue('yuno','ようこそ。私はユノ。届いた荷物を、待っている人へ間違えずに届けたいの。記録を一緒に確かめてくれる？')}${dialogue('nono','山を越えて、谷まで来られたね！')}${all?dialogue('yuno','荷物が出発して、空の中継塔からは届かない知らせの相談が、霧の関所からは送り主の分からない知らせの相談が来たの。どちらへも、この谷から行けるわ。'):''}<p>手伝いたいことを選びましょう。どれからでも取り組めます。</p>${warning()}<h2>荷物と記録のお手伝い</h2><div class="actions">${ids.map(id=>`<button data-expansion="${id}">${expansionQuests[id].short}${state.completed.includes(id)?'（達成済み）':''}</button>`).join('')}${newButtons('valley')}</div>${all?'<h2>これまでの出来事</h2><div class="actions"><button id="ending" class="primary">谷からの届けものを見る</button></div>':''}<h2>旅立ち</h2><div class="actions"><button id="travel">旅先を選ぶ</button></div></section>`;
  bindExpansionButtons();app.querySelector('#ending')?.addEventListener('click',()=>show('valley-ending'));app.querySelector('#travel').onclick=()=>show('travel');
  if(state.storyClimaxComplete&&festivalReady(state.completed)){
   const section=document.createElement('section');section.className='panel';const dataReady=['valley-query-lab','valley-tables-lab'].every(id=>state.completed.includes(id));section.innerHTML=`<h2>記録所に届いた新しい依頼</h2><p>二つの表と名簿を使って届け先を確かめましょう。</p><div class="actions"><button id="record-lab">届け先の発送札を作る${state.completed.includes('valley-query-lab')?'（達成済み）':''}</button><button id="tables-lab">二つの名簿を照らし合わせる${state.completed.includes('valley-tables-lab')?'（達成済み）':''}</button>${dataReady?`<button id="integrity-lab">届け先の記録を守る${state.completed.includes('valley-integrity-lab')?'（達成済み）':''}</button>`:''}</div>${dataReady?'':'<p>二つのお手伝いを終えると、記録を守る新しい依頼が届きます。</p>'}`;app.querySelector('h2').before(section);
   section.querySelector('#record-lab').onclick=()=>{state.recordHistory??=[];show('valley-query-lab');};
   section.querySelector('#tables-lab').onclick=()=>{state.tablesHistory??=[];show('valley-tables-lab');};section.querySelector('#integrity-lab')?.addEventListener('click',()=>{state.integrityHistory??=[];show('valley-integrity-lab');});
  }
