function schedulingLab(){
 const history=state.schedulingHistory??[],p=replayScheduling(history),task=schedulingCases[p.scene],plan=task?planSchedule(task):null,step=plan?.steps[p.step];
 const finished=value=>Object.entries(value).map(([id,time])=>`${id}は${time}刻`).join('、')||'まだありません';
 app.innerHTML=`<h1>仕事の順番を比べる</h1>${dialogue('haru','一つの作業台で二つの仕事を進めるんだ。進め方を変えると、終わる時刻がどう変わるか見てみよう。')}<section class="panel"><h2>目標：三組の仕事を二通りの順番で進める</h2><p>作業台は一台で、１刻に一つの仕事を１刻分進めます。到着順では、始めた仕事が終わるまで続けます。交代制では１刻ずつ進め、終わらなければ待ち列の最後に戻します。切り替えの費用は０です。</p><p>同じ刻に新しい仕事が届いたときは、交代した仕事を待ち列に戻す前に新しい仕事を並べます。同時に届いた仕事は到着予定の順です。表示はその刻の作業を行う直前の状態です。</p><p>進み具合：${p.scene} / ${schedulingCases.length}</p>${task?`<h3 tabindex="-1">${Math.floor(p.scene/2)+1}組目：${task.method==='fcfs'?'到着順':'１刻ずつ交代'}</h3><p>到着予定：${task.jobs.map(([id,arrival,length])=>`${id}は${arrival}刻に届き${length}刻かかる`).join('、')}。</p><p>今は ${step.time} 刻。残り：${Object.entries(step.remaining).map(([id,left])=>`${id}は${left}刻`).join('、')}。完了：${finished(step.finished)}。</p><p>作業台または待ち列にいる仕事：${[step.current,...step.ready].join(' → ')}。順番の規則に従い、次の１刻に進める仕事を選びましょう。</p><div class="actions"><button data-scheduling="run:B">Bを１刻進める</button><button data-scheduling="run:A">Aを１刻進める</button></div>`:`<h3 tabindex="-1">三組を両方の進め方で試しました</h3><p>${p.results.map((row,i)=>`${Math.floor(i/2)+1}組目${i%2?'交代制':'到着順'}：${finished(row)}`).join('。')}。</p><p>短い仕事が交代制で早く終わる例も、両方が同じになる例もあります。この結果は、この模型の到着と仕事の長さによるものです。</p><button id="scheduling-restart">もう一度試す</button>`}<p id="scheduling-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'順番を確かめましょう。'}</p>${warning()}<button id="scheduling-back">風待ちの駅へ戻る</button></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="scheduling-success"><h2 id="scheduling-success">依頼達成<span class="success-detail">仕事の順番を比べる</span></h2>${dialogue('haru','仕事の終わる時刻を比べられた。ありがとう！')}${dialogue('nono','順番で変わる場合と変わらない場合があるんだね。')}<button id="scheduling-finish" class="primary">結果を見る</button></dialog>`:''}`;
 const status=app.querySelector('#scheduling-status'),first=app.querySelector('[data-scheduling]');if(first)first.before(status);
 const act=action=>{const next=[...history,action],value=replayScheduling(next);if(!value){status.textContent=task.method==='fcfs'?'到着順では、始めた仕事を終わるまで続けます。':'１刻ごとに交代し、新しい到着は交代した仕事より先に並びます。';status.focus();return;}state.schedulingHistory=next;if(value.done&&!state.completed.includes('station-schedule-lab'))state.completed.push('station-schedule-lab');persist();schedulingLab();if(value.done)app.querySelector('#success-dialog').showModal();else{const focus=app.querySelector('#scheduling-status');focus.textContent=value.scene!==p.scene?'次の場面の到着予定を確かめましょう。':'次の刻の残りと到着を確かめましょう。';focus.focus();}};
 app.querySelectorAll('[data-scheduling]').forEach(b=>b.onclick=()=>act(b.dataset.scheduling));app.querySelector('#scheduling-restart')?.addEventListener('click',()=>{state.schedulingHistory=[];persist();schedulingLab();app.querySelector('section.panel h3').focus();});app.querySelector('#scheduling-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#scheduling-back').onclick=()=>show('station');
}
function pagesLab(){
 const history=state.pagesHistory??[],p=replayPages(history),task=pageCases[p.scene];
 app.innerHTML=`<h1>道具ごとの番号札を調べる</h1>${dialogue('akari','二つの道具はそれぞれ自分の番号札で記録を探すんだ。実際の棚の場所を一緒に確かめよう。')}<section class="panel"><h2>目標：四つの番号札の置き場所を確かめる</h2><p>この模型では道具ごとに仮想ページの番号と物理棚の枠番号の対応表があり、一つのページは一枠に対応します。同じページ番号でも道具ごとに違う表を使います。実際には同じ枠を共有する設定もありますが、この模型では使いません。</p><p>表に対応がなければ、そのまま変換できず OS に知らせます。理由やその後の処理は状況によって異なります。</p><p>進み具合：${p.scene} / ${pageCases.length}</p>${task?`<h3 tabindex="-1">${p.scene+1}つ目：道具 ${task[0]} のページ ${task[1]}</h3><p>道具Aの表：${Object.entries(pageTables.A).map(([page,frame])=>`ページ${page}→枠${frame}`).join('、')}。<br>道具Bの表：${Object.entries(pageTables.B).map(([page,frame])=>`ページ${page}→枠${frame}`).join('、')}。</p><p>この道具の表を見て物理棚の枠を選びましょう。対応がなければ「対応なし」を選びます。</p><div class="actions"><button data-page="frame:1">枠1</button><button data-page="frame:0">枠0</button><button data-page="frame:2">枠2</button><button data-page="unmapped">対応なし：OSに知らせる</button></div>`:`<h3 tabindex="-1">四つの番号札を確かめました</h3><p>結果：${p.results.map((frame,i)=>`${i+1}つ目 ${frame===null?'対応なし':`枠${frame}`}`).join('、')}。</p><p>道具ごとの対応表を使って仮想ページから物理枠を調べることは、アドレス変換の一部です。ページ内の位置や実際の OS の処理は、この模型では扱っていません。</p><button id="pages-restart">もう一度試す</button>`}<p id="pages-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'道具と番号札を確かめましょう。'}</p>${warning()}<button id="pages-back">星鉄の鍛冶街へ戻る</button></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="pages-success"><h2 id="pages-success">依頼達成<span class="success-detail">道具ごとの番号札を調べる</span></h2>${dialogue('akari','それぞれの道具の表を確かめられたよ。ありがとう！')}${dialogue('nono','同じ番号でも置き場所は違うんだね。')}<button id="pages-finish" class="primary">結果を見る</button></dialog>`:''}`;
 const status=app.querySelector('#pages-status'),first=app.querySelector('[data-page]');if(first)first.before(status);
 const act=action=>{const next=[...history,action],value=replayPages(next);if(!value){status.textContent='道具ごとの表でページ番号を探し、なければ対応なしを選びましょう。';status.focus();return;}state.pagesHistory=next;if(value.done&&!state.completed.includes('forge-pages-lab'))state.completed.push('forge-pages-lab');persist();pagesLab();if(value.done)app.querySelector('#success-dialog').showModal();else{const focus=app.querySelector('#pages-status');focus.textContent='次の道具と番号札を確かめましょう。';focus.focus();}};
 app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>act(b.dataset.page));app.querySelector('#pages-restart')?.addEventListener('click',()=>{state.pagesHistory=[];persist();pagesLab();app.querySelector('section.panel h3').focus();});app.querySelector('#pages-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#pages-back').onclick=()=>show('forge');
}
function swapLab(){
 state.swapProgram??=[];state.swapCase??=0;state.swapShown??=0;state.swapStarted??=false;
 const program=state.swapProgram,index=state.swapCase,done=index===swapCases.length,input=swapCases[index],run=done?null:runSwap(program,input),shown=state.swapShown,last=shown?run.history[shown-1]:null,boxes=last??(input?{A:input[0],B:input[1],C:'空'}:null),atEnd=state.swapStarted&&shown===run?.history.length;
 const describe=id=>{const [to,from]=id.split(':');return `${to}の箱に${from}の印を写す`;};
 app.innerHTML=`<h1>三つの箱で記録を入れ替える</h1>${dialogue('akari','道具が覚えている二つの印を入れ替えたいの。途中で印を失わないよう、手順を作ってくれる？')}<section class="panel"><h2>目標：同じ手順で三組の印を入れ替える</h2><p>AとBの箱の印を入れ替えます。Cは補助の箱で、最初は「空」という印が入っています。「写す」と、写す元の印は残り、写す先の印は上書きされます。「空」も他の印と同じように写せます。</p><h3>手順を組み立てる</h3><p>使いたい操作を順番に並べます。５枚まで。手順を直すと三組の確認は最初からやり直します。</p><ol>${program.map(id=>`<li>${describe(id)}</li>`).join('')||'<li>まだ操作がありません。</li>'}</ol><div class="actions">${swapBoxes.flatMap(to=>swapBoxes.filter(from=>to!==from).map(from=>`<button data-swap-add="${to}:${from}" ${program.length>=5?'disabled':''}>${describe(`${to}:${from}`)}</button>`)).join('')}</div><button id="swap-undo" ${program.length?'':'disabled'}>最後の操作を外す</button><h3 tabindex="-1" id="swap-trial">印で試す</h3><p>進み具合：${index} / ${swapCases.length}</p>${done?'<p>三組の印をすべて入れ替えました。</p><button id="swap-restart">もう一度作る</button>':`<p>${index+1}組目：はじめは A が ${input[0]}、B が ${input[1]}。最後に A を ${input[1]}、B を ${input[0]} にしましょう。</p><p>今の箱：A＝${boxes.A}、B＝${boxes.B}、C＝${boxes.C}</p>${last?`<p>直前に行ったこと：${describe(last.action)}。</p>`:''}${!state.swapStarted?'<button id="swap-start">この手順を試す</button>':!atEnd?'<button id="swap-step">一歩進める</button>':`<p>${run.success?'この組の印を入れ替えられました。':'この組では入れ替わりませんでした。途中で失われた印がないか確かめ、手順を直しましょう。'}</p>${run.success?'<button id="swap-next" class="primary">次の組へ</button>':'<button id="swap-retry">同じ組をもう一度試す</button>'}`}`}<p id="swap-status" role="status">${done?'目標を達成しました！':'操作を組み立てて試しましょう。'}</p>${warning()}<button id="swap-back">鍛冶街へ戻る</button></section>${done?`<dialog id="success-dialog" class="story-success" aria-labelledby="swap-success"><h2 id="swap-success">依頼達成<span class="success-detail">三つの箱で記録を入れ替える</span></h2>${dialogue('akari','どの印も失わず入れ替えられたよ。ありがとう！')}${dialogue('nono','別の箱に写しておくと、あとで使えるんだね！')}<button id="swap-finish" class="primary">結果を見る</button></dialog>`:''}`;
 const redraw=()=>{persist();swapLab();};
 app.querySelectorAll('[data-swap-add]').forEach(button=>button.onclick=()=>{state.swapProgram=[...program,button.dataset.swapAdd];state.swapCase=0;state.swapShown=0;state.swapStarted=false;redraw();(app.querySelector(`[data-swap-add="${button.dataset.swapAdd}"]:not(:disabled)`)??app.querySelector('#swap-undo')).focus({preventScroll:true});});
 app.querySelector('#swap-undo').onclick=()=>{state.swapProgram=program.slice(0,-1);state.swapCase=0;state.swapShown=0;state.swapStarted=false;redraw();app.querySelector('#swap-trial').focus({preventScroll:true});};
 app.querySelector('#swap-start')?.addEventListener('click',()=>{state.swapStarted=true;redraw();(app.querySelector('#swap-step')??app.querySelector('#swap-trial')).focus({preventScroll:true});});
 app.querySelector('#swap-step')?.addEventListener('click',()=>{state.swapShown++;const current=run.history[state.swapShown-1];redraw();const next=app.querySelector('#swap-step')??app.querySelector('#swap-next')??app.querySelector('#swap-retry');next.setAttribute('aria-label',`${describe(current.action)}。今の箱はAが${current.A}、Bが${current.B}、Cが${current.C}。${next.textContent}`);next.focus({preventScroll:true});});
 app.querySelector('#swap-retry')?.addEventListener('click',()=>{state.swapShown=0;state.swapStarted=false;redraw();app.querySelector('#swap-start').focus();});
 app.querySelector('#swap-next')?.addEventListener('click',()=>{state.swapCase++;state.swapShown=0;state.swapStarted=false;if(state.swapCase===swapCases.length&&!state.completed.includes('forge-swap-lab'))state.completed.push('forge-swap-lab');redraw();if(state.swapCase===swapCases.length)app.querySelector('#success-dialog').showModal();else app.querySelector('#swap-trial').focus({preventScroll:true});});
 app.querySelector('#swap-restart')?.addEventListener('click',()=>{state.swapProgram=[];state.swapCase=0;state.swapShown=0;state.swapStarted=false;redraw();app.querySelector('#swap-trial').focus();});app.querySelector('#swap-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#swap-back').onclick=()=>show('forge');
}
