 app.innerHTML=`<h1>${title}</h1>${dialogue('aoi','届け札を読みやすく整えたいの。手伝ってくれる？')}<section class="panel"><h2>目標：${cases.length}つの札を整える</h2><p>進み具合：${p.scene} / ${cases.length}</p><p>${instruction} 半角空白は「␠」で表示します。</p><h3>${p.done?'最後の札':`${p.scene+1}つ目の札`}</h3><p>元の札：${showValue(task.input)}</p><p>${task.goal}</p><p>現在の結果：${showValue(p.value)}</p><p>これまでの操作：${p.ops.length?p.ops.map(x=>names[x]).join(' → '):'まだありません'}</p><div class="actions">${ops.map(op=>`<button data-strings-op="${op}" ${p.done?'disabled':''}>${names[op]}</button>`).join('')}</div><p id="strings-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'操作を試してから、結果を確かめましょう。'}</p>${p.done?'<button id="strings-restart">もう一度試す</button>':`<div class="actions"><button id="strings-undo" ${p.ops.length?'':'disabled'}>一つ戻す</button><button id="strings-check" class="primary">結果を確かめる</button></div>`}${warning()}<p><button id="strings-back">森の文庫へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="strings-success"><h2 id="strings-success">依頼達成<span class="success-detail">${title}</span></h2>${dialogue('aoi','札を整えてくれてありがとう！')}<button id="strings-finish" class="primary">結果を見る</button></dialog>`:''}`;
