 app.innerHTML=`<h1>${title}</h1>${dialogue('aoi','本の番号を手早く探す仕組みを一緒に調べてくれる？')}<section class="panel"><h2>目標：${total}つの場面を確かめる</h2><p>進み具合：${p.scene} / ${total}</p><p>${intro}</p>${body}${p.done?`<p>${explanation}</p>`:''}${warning()}<p><button id="hash-back">森の文庫へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="hash-success"><h2 id="hash-success">依頼達成<span class="success-detail">${title}</span></h2><p>${explanation}</p>${dialogue('aoi','番号棚を一緒に調べてくれてありがとう！')}<button id="hash-finish" class="primary">結果を見る</button></dialog>`:''}`;
