 const summaries=validation?p.results.map((answer,i)=>{const t=validationCases[i];return `${i+1}台目：希望１〜${t.need}、仕様１〜${t.spec}、道具１〜${t.device}個を受付。${answerNames[answer]}。`;}):p.results.map((r,i)=>`${i+1}台目：${r.n}個は仕様が${acceptance(r.expected)}、道具が${acceptance(r.actual)}。`);
