 const act=action=>{const next=[...history,action],value=replayResample(next);if(!value){const status=app.querySelector('#resample-status');status.textContent=p.scene===3?'２枚の元絵と縮小結果を比べましょう。':'各２×２区画の左上を一つずつ選びましょう。';status.focus();return;}state.resampleHistory=next;if(value.done&&!state.completed.includes('garden-image-resample'))state.completed.push('garden-image-resample');persist();resampleLab();if(value.done)app.querySelector('#success-dialog').showModal();else if(action.startsWith('cell:'))app.querySelector(`[data-resample="${action}"]`)?.focus();else{const status=app.querySelector('#resample-status');status.textContent=action==='reduce'?'残した画素で縮めました。':action==='expand'?'残した画素を複製して広げました。':'次の絵を確かめましょう。';status.focus();}};
